effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 original = texture2DCv(inputImg.texture, uv);
float rad = trailAngle * 0.0174532925;
vec2 dir = vec2(cos(rad), sin(rad));
float aspect = acScreenSize.x / max(acScreenSize.y, 1.0);
dir.y /= aspect;
float pulse = 1.0 + sin(acTime * pulseSpeed * 3.14159) * 0.25;
vec3 accumGhosts = vec3(0.0);
float maxAlpha = original.a;
int numGhosts = int(clamp(ghostCount, 2.0, 10.0));
for(int i = 1; i <= 10; i++) {
if (i > numGhosts) break;
float fi = float(i);
float stepFraction = fi / float(numGhosts);
float ghostWeight = pow(decay, fi);
float totalDist = fi * trailDist * pulse;
vec2 sampleUv = uv + dir * totalDist;
float currentScale = pow(scaleStep, fi);
sampleUv = (sampleUv - 0.5) / currentScale + 0.5;
vec2 chromaOff = dir * (chromaSplit * fi);
float sR = texture2DCv(inputImg.texture, clamp(sampleUv + chromaOff, 0.0, 1.0)).r;
float sG = texture2DCv(inputImg.texture, clamp(sampleUv, 0.0, 1.0)).g;
float sB = texture2DCv(inputImg.texture, clamp(sampleUv - chromaOff, 0.0, 1.0)).b;
vec4 sFull = texture2DCv(inputImg.texture, clamp(sampleUv, 0.0, 1.0));
vec3 ghostRgb = vec3(sR, sG, sB);
vec3 tint = mix(ghostTint1.rgb, ghostTint2.rgb, stepFraction);
ghostRgb = mix(ghostRgb, ghostRgb * tint * 2.0, 0.7);
accumGhosts += ghostRgb * ghostWeight * sFull.a;
maxAlpha = max(maxAlpha, sFull.a * ghostWeight);
}
vec4 result;
if (blendMode == 0) {
float ghostAlpha = clamp(length(accumGhosts) * 0.5, 0.0, 1.0);
vec3 mixed = mix(original.rgb, accumGhosts, ghostAlpha * (1.0 - original.a * 0.5));
result = vec4(mixed + accumGhosts * 0.5, maxAlpha);
} else if (blendMode == 2) {
vec3 screened = 1.0 - (1.0 - original.rgb) * (1.0 - clamp(accumGhosts, 0.0, 1.0));
result = vec4(screened, maxAlpha);
} else {
result = vec4(original.rgb + accumGhosts, maxAlpha);
}
result = clamp(result, 0.0, 1.0);
gl_FragColor = mix(original, result, alpha);
}
